        long long *oldCurrent = current;
        current = next;
        next = oldCurrent;
        partialCount = nextCount;
    }

    finalizePartials<<<1, 128, 128 * sizeof(long long)>>>(
        current, static_cast<unsigned int>(partialCount), output);
}
